// === Tab: mySketch ===
let g = 0.005;
let particles = new Array(700);

////////////////////////////////////////////////////////////////////////////////

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	noStroke();

	for (i = 0; i < particles.length; i++) {
		particles[i] = new Particle();

		particles[i].px = random(width);
		particles[i].py = random(height);

		if (i % 2 == 0) particles[i].m =  randomGaussian() * 8;
		else            particles[i].m = -randomGaussian() * 8;
	}
}

////////////////////////////////////////////////////////////////////////////////

function draw() {
	background(32);

	for (me = 0; me < particles.length; me++) {
		particles[me].resetAcceleration();

		for (neighbor = 0; neighbor < particles.length; neighbor++) {
			particles[me].updatePartialAcceleration(particles[neighbor]);
		}
	}

	for (i = 0; i < particles.length; i++) {
		particles[i].updateVelocityAndPosition();

		let opacity = sqrt(particles[i].vx * particles[i].vx + particles[i].vy * particles[i].vy) * 128;

		if (particles[i].m < 0) fill(255, opacity);
		else                    fill(255, 0, 153, opacity);

		let radius = abs(particles[i].m);
		ellipse(particles[i].px, particles[i].py, radius, radius);
	}
}

////////////////////////////////////////////////////////////////////////////////

function mousePressed() {
	g *= -1;
}


////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////


class Particle {
	px, py, vx, vy, ax, ay, m;

////////////////////////////////////////////////////////////////////////////////

  function resetAcceleration() {
		ax = 0;
		ay = 0;
	}

////////////////////////////////////////////////////////////////////////////////

  function updatePartialAcceleration(neighbor) {
		if (neighbor != this) {
			dx = px - neighbor.px;
			dy = py - neighbor.py;

			let d = dx*dx + dy*dy;
			if (d < 1) d = 1;

			let common = m * neighbor.m / d;

			ax += common * dx;
			ay += common * dy;
		}
	}

////////////////////////////////////////////////////////////////////////////////

  function updateVelocityAndPosition() {
		vx = vx * 0.99 + ax * g;
		vy = vy * 0.99 + ay * g;

		px += vx;
		py += vy;

		if ((px < 0 && vx < 0) || (px > width  && vx > 0))   vx = -vx;
		if ((py < 0 && vy < 0) || (py > height && vy > 0))   vy = -vy;
	}
}

